import * as THREE from 'three/webgpu';
import { texture, MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position and transforms
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ = [0, 0, 0], scaleXYZ = [1, 1, 1] } = config.scenePosition;
    group.position.set(x, y, z);
    group.rotation.order = 'YXZ';
    group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
    group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
  }

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Create TSL material with textured surface
  const material = new MeshBasicNodeMaterial();
  const textures = [];

  if (config.imageUrl) {
    const map = ctx.textureLoader.load(config.imageUrl);
    map.colorSpace = THREE.SRGBColorSpace;
    textures.push(map);
    material.colorNode = texture(map);
  }

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content via fontAtlas (MSDF, never TextGeometry)
  if (config.textContent && Array.isArray(config.textContent)) {
    for (const textItem of config.textContent) {
      const textMesh = ctx.fontAtlas.createTextMesh({
        text: textItem.text,
        fontSize: textItem.fontSize || 0.34,
        fontFamily: 'Lora',
        fontWeight: textItem.fontWeight || '400',
        color: 0xE8ECF2, // paper color from design tokens
        anchorX: 'center',
        anchorY: 'middle',
        maxWidth: 0.9
      });
      textMesh.position.z = 0.01; // Slightly above plane to prevent z-fighting
      group.add(textMesh);
    }
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    }
  }

  // Event handlers (attach to userData, never use renderer.domElement.addEventListener)
  group.userData.handlers = {
    onPointerOver: null,
    onPointerOut: null,
    onClick: null,
    onPointerDown: null,
    onPointerUp: null
  };

  // Cleanup function (must dispose resources and kill GSAP timelines)
  group.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose textures
    textures.forEach(tex => tex.dispose());
  };

  return group;
}
